from pathlib import Path
O=Path('/workspace/output/fluxweave/elements')
def add(k,s):
 p=O/k/'element.css';p.write_text(p.read_text()+'\n'+s+'\n')
add('slope','''[data-el="fluxweave-slope"]:not(.dumbbell)>.pair{--fluxweave-dx:60cqw;--fluxweave-dy:calc((var(--a) - var(--b))/var(--max)*.8*(100cqh - var(--gap-lg)*2));}[data-el="fluxweave-slope"]:not(.dumbbell)>.pair::after{left:0;top:calc(100% - var(--a)/var(--max)*80%);width:hypot(var(--fluxweave-dx),var(--fluxweave-dy));height:var(--stroke);rotate:atan2(var(--fluxweave-dy),var(--fluxweave-dx));transform-origin:0 50%;background:var(--n-4);}[data-el="fluxweave-slope"]:not(.dumbbell)>.pair.on::after{background:var(--a1);}[data-el="fluxweave-slope"]:not(.dumbbell)>.pair>.a,[data-el="fluxweave-slope"]:not(.dumbbell)>.pair>.b{transform:translateX(-50%);bottom:calc(var(--a)/var(--max)*80% + 9px);line-height:var(--label-line);}[data-el="fluxweave-slope"]:not(.dumbbell)>.pair>.b{bottom:calc(var(--b)/var(--max)*80% + 9px);}[data-el="fluxweave-slope"]:not(.dumbbell)>.pair>.a::after,[data-el="fluxweave-slope"]:not(.dumbbell)>.pair>.b::after{content:"";position:absolute;left:calc(50% - 4px);top:calc(100% + 5px);width:8px;height:8px;border-radius:50%;background:var(--n-6);}[data-el="fluxweave-slope"]:not(.dumbbell)>.pair.on>.a::after,[data-el="fluxweave-slope"]:not(.dumbbell)>.pair.on>.b::after{background:var(--a1);}[data-el="fluxweave-slope"]:not(.dumbbell)>.heads{border-bottom:0;}''')
add('funnel','''[data-el="fluxweave-funnel"]>.stage{position:relative;isolation:isolate;width:100%;padding:0;background:none!important;min-width:0;}[data-el="fluxweave-funnel"]>.stage::before{content:"";position:absolute;left:50%;top:0;bottom:0;transform:translateX(-50%);width:calc(clamp(0,var(--v),100)*1%);background:var(--a1-2-soft);border-radius:var(--radius);z-index:-1;}[data-el="fluxweave-funnel"]>.stage:nth-child(2n)::before{background:var(--a1-3-soft);}[data-el="fluxweave-funnel"]>.stage>.name{max-width:55%;}[data-el="fluxweave-funnel"]>.stage>.fig{min-width:15%;text-align:left;}''')
print('slope numeric route and exact funnel bands')
